question.answer:
STANDARD_KPA = 3.5


def describe(valve_id: str, pressure_kpa: float = STANDARD_KPA) -> str:
    return f"{valve_id} at {pressure_kpa} kPa"


def reading(valve_id: str, pressure_kpa: float = STANDARD_KPA, timeout_s: int = 30) -> str:
    return f"{valve_id} {pressure_kpa} {timeout_s}"


def quick_check(valve_id: str) -> str:
    return reading(valve_id, timeout_s=5)

