question.answer:
SHIFT = "night"


# Supplied and broken. Do not change these two.
def broken_record(event, journal=[]):
    journal.append(event)
    return journal


def broken_label(event, shift=SHIFT):
    return f"{shift}: {event}"


def record(event: str, journal: list[str] | None = None) -> list[str]:
    if journal is None:
        journal = []
    journal.append(event)
    return journal


def label(event: str, shift: str | None = None) -> str:
    if shift is None:
        shift = SHIFT
    return f"{shift}: {event}"

