question.answer:
# Three Java-style overloads. Supplied. Do not change them.
def legacy_valve(valve_id):
    return f"one arg: {valve_id}"


def legacy_valve(valve_id, pressure_kpa):
    return f"two args: {valve_id} {pressure_kpa}"


def legacy_valve(valve_id, pressure_kpa, timeout_s):
    return f"three args: {valve_id} {pressure_kpa} {timeout_s}"


def open_valve(valve_id: str, /, *, pressure_kpa: float, timeout_s: int = 30, **audit: str) -> str:
    return f"{valve_id} to {pressure_kpa} kPa over {timeout_s}s {audit}"


def forward(*args: object, **kwargs: object) -> str:
    return open_valve(*args, **kwargs)

